head.script:
// [FAIL] 공통 메소드 setSize(width, height) 호출 시
//        [A] fusionchart 는 내부 SVG 까지 새 크기로 다시 그려지지만,
//        [B] fwFunnelChart / [C] fwBulletChart / [D] mapchart 는 컨테이너 영역만 바뀌고
//        내부 SVG 는 최초 생성 크기(300x200) 그대로 남는다.
//        getSize() 는 네 컴포넌트 모두 설정값을 그대로 반환하므로 반환값만으로는 정상으로 보인다.
//        (fw* 차트 7종 : fwBullet / fwFunnel / fwGantt / fwGauge / fwPyramid / fwSpark / fwRealtime 동일)
//        (mapchart 는 createMap() 이 생성 시점에 svg 의 width/height attribute 를 1회만 설정하고
//         viewBox 도 없어, 축소 시에는 svg 가 컨테이너 밖으로 넘친다.)

// 초기 크기 (세 차트 동일 조건)
scwin.INIT_W = "300px";
scwin.INIT_H = "200px";



scwin.onpageload = function () {
    // 최초 차트 렌더가 끝난 뒤, 초기 크기를 결과창에 남겨 setSize 전후 비교 기준으로 사용한다.
    setTimeout(function () {
        scwin.printAll("초기 상태");
    }, 1000);
};



// setSize 축소 : 300px x 150px
scwin.btn_shrink_onclick = function (e) {
    scwin.callSetSize("300px", "150px");
};



// setSize 확대 : 500px x 400px
scwin.btn_expand_onclick = function (e) {
    scwin.callSetSize("500px", "400px");
};



// setSize 초기 크기 복원
scwin.btn_restore_onclick = function (e) {
    scwin.callSetSize(scwin.INIT_W, scwin.INIT_H);
};



// 현재 크기 측정 (setSize 없이 실측만)
scwin.btn_measure_onclick = function (e) {
    scwin.printAll("현재 크기");
};



// 네 차트에 동일한 setSize 를 호출하고, 렌더가 끝난 뒤 실측값을 출력한다.
scwin.callSetSize = function (strWidth, strHeight) {
    chart_fusion.setSize(strWidth, strHeight);
    chart_funnel.setSize(strWidth, strHeight);
    chart_bullet.setSize(strWidth, strHeight);
    chart_map.setSize(strWidth, strHeight);

    setTimeout(function () {
        scwin.printAll("setSize(" + strWidth + ", " + strHeight + ")");
    }, 1000);
};



scwin.printAll = function (strTitle) {
    scwin.setReturnValue("● " + strTitle);
    scwin.printSize("[A] fusionchart  ", "chart_fusion");
    scwin.printSize("[B] fwFunnelChart", "chart_funnel");
    scwin.printSize("[C] fwBulletChart", "chart_bullet");
    scwin.printSize("[D] mapchart     ", "chart_map");
};



// getSize 반환값 / 컨테이너 div 실측 / 내부 SVG 실측 을 함께 출력한다.
scwin.printSize = function (strLabel, strID) {
    var comp = $p.getComponentById(strID);
    var elComp = document.getElementById(comp.getID());
    var elSvg = elComp ? elComp.querySelector("svg") : null;

    var strGet = comp.getSize("width") + "x" + comp.getSize("height");
    var strDiv = elComp ? elComp.offsetWidth + "x" + elComp.offsetHeight : "확인불가";
    var strSvg = "확인불가";

    if (elSvg) {
        var rect = elSvg.getBoundingClientRect();
        var nSvgW = elSvg.getAttribute("width") || Math.round(rect.width);
        var nSvgH = elSvg.getAttribute("height") || Math.round(rect.height);
        strSvg = nSvgW + "x" + nSvgH;
    }

    scwin.setReturnValue(strLabel + " : getSize " + strGet + " / div " + strDiv + " / svg " + strSvg);
};



// ===== 리턴 값 출력 영역 (body_bottom.xml inline 복사) =====
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
